using namespace std;

struct Tracer {
    string name;
    Tracer(string n) : name(n) { cout << "create  " << name << "\n"; }
    ~Tracer() { cout << "destroy " << name << "\n"; }
};

int main() {
    Tracer a("stack-A");              // automatic: lives until the closing brace
    Tracer b("stack-B");
    Tracer* raw = new Tracer("heap-raw");   // heap: we must delete it ourselves
    {
        auto owned = make_unique<Tracer>("heap-owned");  // heap, but owned by a stack object
        cout << "inner scope ends\n";
    }                                 // owned's destructor frees the heap object here
    vector<int> v(1000, 7);           // the vector object is on the stack, its 1000 ints on the heap
    cout << "vector size " << v.size() << "\n";
    delete raw;                       // forget this line and the object leaks
    cout << "main ends\n";
}                                     // b is destroyed first, then a (reverse order)

#include <bits/stdc++.h>
using namespace std;

// RAII: acquire in the constructor, release in the destructor
class Guard {
    string name;
public:
    explicit Guard(string n) : name(move(n)) { cout << "acquire " << name << "\n"; }
    ~Guard() { cout << "release " << name << "\n"; }
    Guard(const Guard&) = delete;             // one owner only
    Guard& operator=(const Guard&) = delete;
};

void work(bool fail) {
    Guard g1("lock");
    Guard g2("file");
    if (fail) throw runtime_error("boom");    // stack unwinding still runs both destructors
    cout << "work done\n";
}

int main() {
    work(false);
    try {
        work(true);
    } catch (const exception& e) {
        cout << "caught: " << e.what() << "\n";
    }
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    // Iterator invalidation: a classic dangling reference.
    vector<int> v = {1, 2, 3};
    int* first = &v[0];
    cout << "before push_back: *first = " << *first << "\n";
    v.reserve(1000);                  // reallocation moves elements, 'first' now dangles
    cout << "pointer still equals data()? " << (first == v.data() ? "yes" : "no (dangling)") << "\n";
    // Reading *first here would be use-after-free; ASan reports it.
    first = v.data();                 // fix: re-fetch after anything that may reallocate
    cout << "re-fetched: *first = " << *first << "\n";

    // Leak vs RAII: raw new without delete leaks, unique_ptr cannot.
    {
        auto p = make_unique<int[]>(5);   // matches delete[] automatically
        for (int i = 0; i < 5; i++) p[i] = i * i;   // initialised, no uninitialised read
        for (int i = 0; i < 5; i++) cout << p[i] << " ";
        cout << "\n";
    }                                     // freed here
    // Build and run tests with: g++ -fsanitize=address,undefined
    cout << "done\n";
}

#include <bits/stdc++.h>
using namespace std;

struct Widget {
    int id;
    explicit Widget(int i) : id(i) { cout << "Widget " << id << " created\n"; }
    ~Widget() { cout << "Widget " << id << " destroyed\n"; }
};

unique_ptr<Widget> make(int id) { return make_unique<Widget>(id); }  // return by value: moved/elided

void borrow(const Widget& w) { cout << "borrowing " << w.id << "\n"; }  // just uses it
void consume(unique_ptr<Widget> w) { cout << "consuming " << w->id << "\n"; }  // takes ownership

int main() {
    auto a = make(1);
    borrow(*a);                       // pass the object, not the smart pointer
    consume(move(a));                 // explicit move: ownership leaves 'a'
    cout << "a is " << (a ? "set" : "empty") << "\n";
    vector<unique_ptr<Widget>> v;     // a vector of unique_ptr works because it is move-only
    v.push_back(make(2));
    v.push_back(make(3));
    cout << "vector holds " << v.size() << "\n";
    // copying would not compile: auto b = v[0];
}

#include <bits/stdc++.h>
using namespace std;

struct Big { int data[4]; ~Big() { cout << "Big destroyed\n"; } };

int main() {
    shared_ptr<Big> a = make_shared<Big>();    // one allocation: object + control block
    cout << "use_count after create: " << a.use_count() << "\n";
    {
        shared_ptr<Big> b = a;                 // copy: strong count +1 (atomic)
        weak_ptr<Big> w = a;                   // weak count +1, strong unchanged
        cout << "use_count with copy: " << a.use_count() << "\n";
        cout << "weak observers: " << w.use_count() << " owners\n";
    }
    cout << "use_count after scope: " << a.use_count() << "\n";

    // The deleter is type-erased: same shared_ptr<int> type, different deleters.
    shared_ptr<int> p1(new int(5), [](int* p) { cout << "deleter 1\n"; delete p; });
    shared_ptr<int> p2(new int(6), [](int* p) { cout << "deleter 2\n"; delete p; });
    cout << "same type: " << boolalpha << is_same_v<decltype(p1), decltype(p2)> << "\n";
    a.reset();                                 // count reaches 0, Big destroyed
    cout << "end\n";
}

#include <bits/stdc++.h>
using namespace std;

struct Node {
    string name;
    shared_ptr<Node> child;      // owning edge: parent -> child
    weak_ptr<Node> parent;       // non-owning edge: child -> parent
    Node(string n) : name(n) {}
    ~Node() { cout << name << " destroyed\n"; }
};

int main() {
    auto parent = make_shared<Node>("parent");
    auto child = make_shared<Node>("child");
    parent->child = child;
    child->parent = parent;                    // weak: does not raise parent's count
    cout << "parent count: " << parent.use_count() << "\n";
    cout << "child count: " << child.use_count() << "\n";

    if (auto p = child->parent.lock())         // lock() gives a shared_ptr or empty
        cout << "child sees parent: " << p->name << "\n";

    weak_ptr<Node> watch = child;
    child.reset();                             // parent still owns child
    cout << "child alive via parent: " << (watch.expired() ? "no" : "yes") << "\n";
    parent.reset();                            // frees parent, then child
    cout << "child expired: " << boolalpha << watch.expired() << "\n";
}

#include <bits/stdc++.h>
using namespace std;

static int alive = 0;                  // instance counter, handy in tests

struct A;
struct B;
struct A { shared_ptr<B> b; A() { alive++; } ~A() { alive--; } };
struct B { shared_ptr<A> a; B() { alive++; } ~B() { alive--; } };   // cycle: strong both ways

struct C;
struct D;
struct C { shared_ptr<D> d; C() { alive++; } ~C() { alive--; } };
struct D { weak_ptr<C> c; D() { alive++; } ~D() { alive--; } };     // weak back edge

int main() {
    {
        auto a = make_shared<A>();
        auto b = make_shared<B>();
        a->b = b;
        b->a = a;                       // a and b keep each other alive
    }                                   // locals gone, counts stay at 1 each
    cout << "alive after cycle scope: " << alive << "\n";   // 2 leaked objects

    alive = 0;
    {
        auto c = make_shared<C>();
        auto d = make_shared<D>();
        c->d = d;
        d->c = c;                       // weak: no extra count on c
    }
    cout << "alive after weak scope: " << alive << "\n";     // 0
}

