struct Item {
    int v;
    explicit Item(int x) : v(x) { cout << "Item " << v << "\n"; }
};

class Secret {
    Secret() { cout << "private ctor\n"; }
public:
    static shared_ptr<Secret> create() { return shared_ptr<Secret>(new Secret()); }  // make_shared cannot reach a private ctor
};

void take(shared_ptr<Item> a, int n) { cout << "take " << a->v << " " << n << "\n"; }

int main() {
    auto u = make_unique<Item>(1);           // no naked new, type written once
    auto s = make_shared<Item>(2);           // one allocation: object + control block
    take(make_shared<Item>(3), 7);           // safe argument pattern
    auto sec = Secret::create();             // factory case where make_shared is not usable
    auto arr = make_unique<int[]>(3);        // value-initialised array
    cout << arr[0] << arr[1] << arr[2] << "\n";
    cout << "u=" << u->v << " s=" << s->v << " count=" << s.use_count() << "\n";
}

#include <bits/stdc++.h>
using namespace std;

// Pretend C API: handles are opened and closed through functions.
int open_handle(const char* name) { cout << "open " << name << "\n"; return 42; }
void close_handle(int h) { cout << "close " << h << "\n"; }

struct FileCloser {                          // stateless functor: no size overhead
    void operator()(FILE* f) const { if (f) { fclose(f); cout << "fclose called\n"; } }
};
using FilePtr = unique_ptr<FILE, FileCloser>;

int main() {
    FilePtr f(tmpfile());                    // closed automatically at end of scope
    if (f) fputs("hello", f.get());
    cout << "sizeof FilePtr == sizeof(void*): " << boolalpha << (sizeof(FilePtr) == sizeof(void*)) << "\n";

    // A pointer-sized deleter lambda for shared_ptr: it lives in the control block.
    shared_ptr<char> buf((char*)malloc(16), [](char* p) { free(p); cout << "free called\n"; });
    cout << "buffer owned, use_count " << buf.use_count() << "\n";

    // An int handle is not a pointer: wrap it in a tiny RAII struct instead.
    struct Handle {
        int h;
        explicit Handle(int x) : h(x) {}
        ~Handle() { close_handle(h); }
    } h(open_handle("data.bin"));
    cout << "using handle " << h.h << "\n";
}

#include <bits/stdc++.h>
using namespace std;

struct Task : enable_shared_from_this<Task> {
    string name;
    explicit Task(string n) : name(n) {}
    ~Task() { cout << name << " destroyed\n"; }

    function<void()> make_callback() {
        auto self = shared_from_this();      // shares the existing control block
        return [self]() { cout << "callback runs for " << self->name << "\n"; };
    }
    shared_ptr<Task> wrong() { return shared_ptr<Task>(this); }   // second control block: bug
};

int main() {
    function<void()> cb;
    {
        auto t = make_shared<Task>("job");
        cb = t->make_callback();
        cout << "use_count: " << t.use_count() << "\n";   // t + the lambda's copy
    }                                                       // t gone, but cb keeps it alive
    cb();
    cb = nullptr;                                           // last owner released here

    try {
        Task local("on-stack");
        local.shared_from_this();                           // not owned by a shared_ptr
    } catch (const bad_weak_ptr&) {
        cout << "bad_weak_ptr caught\n";
    }
}

#include <bits/stdc++.h>
using namespace std;

template <class T>
class MyUnique {
    T* p_ = nullptr;
public:
    explicit MyUnique(T* p = nullptr) noexcept : p_(p) {}
    ~MyUnique() { delete p_; }
    MyUnique(const MyUnique&) = delete;                  // no copies
    MyUnique& operator=(const MyUnique&) = delete;
    MyUnique(MyUnique&& o) noexcept : p_(exchange(o.p_, nullptr)) {}   // steal, leave source empty
    MyUnique& operator=(MyUnique&& o) noexcept {
        if (this != &o) reset(o.release());               // self-move safe
        return *this;
    }
    T* release() noexcept { return exchange(p_, nullptr); }
    void reset(T* q = nullptr) noexcept { T* old = exchange(p_, q); delete old; }
    explicit operator bool() const noexcept { return p_ != nullptr; }
    T& operator*() const { return *p_; }
    T* operator->() const { return p_; }
};

struct Res { int id; Res(int i) : id(i) { cout << "Res " << id << " up\n"; } ~Res() { cout << "Res " << id << " down\n"; } };

int main() {
    MyUnique<Res> a(new Res(1));
    MyUnique<Res> b(move(a));                 // a becomes empty
    cout << "a " << (a ? "set" : "empty") << ", b " << (b ? "set" : "empty") << "\n";
    b = MyUnique<Res>(new Res(2));            // old Res 1 is deleted by reset
    vector<MyUnique<Res>> v;
    v.push_back(move(b));                     // vector can move it because move is noexcept
    cout << "id in vector: " << v[0]->id << "\n";
}

#include <bits/stdc++.h>
using namespace std;

struct Block {
    atomic<int> strong{1};
    atomic<int> weak{1};                      // the strong group holds one weak ref
};

// Increment only if strong > 0: the safe core of weak_ptr::lock().
bool try_acquire(Block& b) {
    int n = b.strong.load(memory_order_relaxed);
    while (n != 0) {                          // never revive a dead object
        if (b.strong.compare_exchange_weak(n, n + 1, memory_order_relaxed)) return true;
    }
    return false;
}

int main() {
    Block b;
    const int T = 4, N = 100000;
    vector<thread> ts;
    for (int t = 0; t < T; t++)
        ts.emplace_back([&] {
            for (int i = 0; i < N; i++) {
                if (try_acquire(b))
                    b.strong.fetch_sub(1, memory_order_acq_rel);   // release: acq_rel on the decrement
            }
        });
    for (auto& t : ts) t.join();
    cout << "strong after threads: " << b.strong.load() << "\n";   // back to 1

    if (b.strong.fetch_sub(1, memory_order_acq_rel) == 1)           // last owner drops
        cout << "last owner: destroy object, then drop the group's weak ref\n";
    cout << "try_acquire on dead block: " << boolalpha << try_acquire(b) << "\n";
    if (b.weak.fetch_sub(1, memory_order_acq_rel) == 1)
        cout << "weak hit 0: free control block\n";
}

#include <bits/stdc++.h>
using namespace std;

// A tiny "heap profiler": count live allocations by label.
map<string, int> live;
struct Tracked {
    string label;
    explicit Tracked(string l) : label(l) { live[label]++; }
    Tracked(const Tracked& o) : label(o.label) { live[label]++; }
    ~Tracked() { live[label]--; }
};

struct Cache { vector<shared_ptr<Tracked>> items; };   // unbounded: grows forever

void handle_request(int i, Cache& cache) {
    Tracked temp("request");                         // freed at end of function: fine
    if (i % 2 == 0)
        cache.items.push_back(make_shared<Tracked>("cached"));   // never evicted
}

void report(int step) {
    cout << "after " << step << " requests: ";
    for (auto& [k, v] : live) cout << k << "=" << v << " ";
    cout << "\n";
}

int main() {
    Cache cache;
    for (int i = 1; i <= 300; i++) {
        handle_request(i, cache);
        if (i % 100 == 0) report(i);     // compare snapshots: "cached" keeps growing, "request" stays 0
    }
    cache.items.clear();                  // fix idea: bound or evict the cache
    report(0);
}

#include <bits/stdc++.h>
using namespace std;

struct Engine { int hp = 200; };

struct Car {
    unique_ptr<Engine> engine = make_unique<Engine>();   // exclusive owner of its engine
    string name;
    explicit Car(string n) : name(n) {}
};

void print_hp(const Engine& e) { cout << "hp " << e.hp << "\n"; }       // reference: non-null, borrowed
void maybe_print(const Engine* e) { cout << (e ? "engine present\n" : "no engine\n"); }  // raw: nullable, non-owning

struct Config { string mode; };

int main() {
    Car c("sedan");
    print_hp(*c.engine);
    maybe_print(c.engine.get());
    maybe_print(nullptr);

    shared_ptr<const Config> cfg = make_shared<const Config>(Config{"fast"});  // shared immutable snapshot
    weak_ptr<const Config> observer = cfg;                                     // observes, does not own
    auto reader1 = cfg;                                                        // two readers share ownership
    cout << "owners: " << cfg.use_count() << "\n";
    reader1.reset();
    cfg.reset();                                                               // last owner gone
    cout << "observer sees config: " << boolalpha << !observer.expired() << "\n";

    int plain = 5;                                                             // often the best choice: a value
    cout << "value needs no pointer: " << plain << "\n";
}
